SELECT window_number as windowNumber, count(*) as count, ROUND(AVG(CASE WHEN satisfaction_select = 1 THEN 100 WHEN satisfaction_select = 2 THEN 85 WHEN satisfaction_select = 3 THEN 70 WHEN satisfaction_select = 4 THEN 50 ELSE 0 END), 2) AS avgScore FROM questionnaire_info
and window_number = #{windowNumber}
GROUP BY window_number ORDER BY CONVERT(window_number, SIGNED)
